#!/usr/bin/env python3
from __future__ import annotations

import shutil
from pathlib import Path

from docx import Document


HERE = Path(__file__).resolve().parent


def norm(text: str) -> str:
    return " ".join(text.split())


def remove_paragraph(paragraph) -> None:
    el = paragraph._element
    el.getparent().remove(el)
    paragraph._p = paragraph._element = None


def replace_paragraphs(doc: Document, replacements: dict[str, str]) -> int:
    count = 0
    for p in doc.paragraphs:
        key = norm(p.text)
        if key in replacements:
            p.text = replacements[key]
            count += 1
    return count


def find_paragraph(doc: Document, startswith: str):
    for p in doc.paragraphs:
        if norm(p.text).startswith(startswith):
            return p
    raise ValueError(f"Paragraph starting with {startswith!r} not found")


