def insert_note5(doc: Document) -> None:
    anchor = find_paragraph(doc, "Supplementary Figures")
    for text in SI_NOTE5_PARAGRAPHS:
        anchor.insert_paragraph_before(text)


def rebuild_table_section(doc: Document) -> None:
    paragraphs = list(doc.paragraphs)
    start_idx = next(i for i, p in enumerate(paragraphs) if norm(p.text).startswith("Supplementary Tables"))
    end_idx = next(i for i, p in enumerate(paragraphs) if norm(p.text).startswith("Supplementary Data Availability"))
    for _ in range(end_idx - start_idx):
        remove_paragraph(doc.paragraphs[start_idx])
    end = find_paragraph(doc, "Supplementary Data Availability")
    for text in SI_TABLE_SECTION:
        end.insert_paragraph_before(text)


def clone_doc(src: Path, dst: Path) -> Document:
    shutil.copy2(src, dst)
    return Document(dst)


def main() -> None:
    m_src = HERE / "manuscript_v4.docx"
    s_src = HERE / "si_v4.docx"
    m_dst = HERE / "manuscript_v5.docx"
    s_dst = HERE / "si_v5.docx"

    m_doc = clone_doc(m_src, m_dst)
    m_count = replace_paragraphs(m_doc, MANUSCRIPT_REPLACEMENTS)
    m_doc.save(m_dst)

    s_doc = clone_doc(s_src, s_dst)
    s_count = replace_paragraphs(s_doc, SI_REPLACEMENTS)
    insert_note5(s_doc)
    rebuild_table_section(s_doc)
    s_doc.save(s_dst)

    print(f"{m_dst}: updated {m_count} paragraphs")
    print(f"{s_dst}: updated {s_count} figure paragraphs, inserted Note 5 and rebuilt table section")


if __name__ == "__main__":
    main()
